window.OVA_CONTENT={"slug":"seccion-01-ecosistemas-y-ciclos-biogeoquimicos","title":"Ecosistemas y ciclos biogeoquímicos","minutes":40,"summary":"Analiza flujos de energía, materia, agua y nutrientes en sistemas agrícolas modificados por la producción.","objective":"Relacionar procesos ecológicos con entradas, extracciones y pérdidas agroindustriales.","stages":[{"eyebrow":"Sistema","title":"1. Producción dentro de un ecosistema","reading":"Un ecosistema integra organismos y componentes físicos mediante flujos de energía y circulación de materia. La agricultura modifica esas relaciones al seleccionar especies, remover biomasa e incorporar insumos.","application":"La empresa depende de procesos que continúan fuera de sus límites físicos: disponibilidad de agua, fertilidad, polinización y regulación biológica.","activity":{"type":"choice","question":"¿Qué visión es más completa?","options":["La producción interactúa con organismos, suelo, agua y clima","La finca es independiente de su entorno","Solo importa el producto cosechado"],"answer":[0],"success":"El sistema productivo forma parte de redes ecológicas."}},{"eyebrow":"Ciclos","title":"2. Reservorios y transformaciones","reading":"Carbono, nitrógeno, fósforo y agua circulan entre reservorios. Los ciclos difieren en sus depósitos y velocidades, pero todos incluyen entradas, transformaciones internas y salidas.","application":"Reconocer el ciclo permite identificar dónde una práctica productiva altera disponibilidad o genera pérdidas.","activity":{"type":"match","question":"Relaciona elemento y proceso destacado.","pairs":[{"label":"Carbono","value":"biomasa","option":"Biomasa y atmósfera"},{"label":"Nitrógeno","value":"microbios","option":"Transformaciones microbianas"},{"label":"Fósforo","value":"sedimentos","option":"Reservorios geológicos"},{"label":"Agua","value":"transporte","option":"Transporte de sustancias"}],"answer":["biomasa","microbios","sedimentos","transporte"],"success":"Cada ciclo conecta compartimentos diferentes."}},{"eyebrow":"Extracción","title":"3. Qué ocurre al cosechar","reading":"La cosecha retira biomasa y nutrientes que circularon en el sistema. Si las salidas superan la reposición y el reciclaje, puede disminuir la fertilidad y aumentar la dependencia de insumos.","application":"Un balance de nutrientes considera cantidad extraída, pérdidas, retornos y disponibilidad real.","activity":{"type":"order","question":"Ordena una lectura del balance.","items":["Cuantificar entradas","Reconocer transformaciones internas","Estimar biomasa extraída","Identificar pérdidas","Definir reposición y reciclaje"],"answer":[0,1,2,3,4],"success":"La cosecha es una salida ecológica y económica."}},{"eyebrow":"Intensificación","title":"4. Presiones que deben vigilarse","reading":"La simplificación del sistema, la labranza, el uso de insumos y el riego pueden modificar suelo, agua, biodiversidad y poblaciones de organismos. Los efectos dependen de dosis, frecuencia y contexto.","application":"Medir el rendimiento sin indicadores ambientales deja incompleta la evaluación.","activity":{"type":"multi","question":"Selecciona presiones relevantes.","options":["Erosión del suelo","Pérdida de nutrientes","Contaminación del agua","Número de página del informe"],"answer":[0,1,2],"success":"Las presiones conectan práctica y cambio ambiental."}},{"eyebrow":"Caso aplicado","title":"5. Exportación de biomasa","reading":"Una empresa aumenta cosechas sucesivas sin revisar análisis de suelo ni retorno de residuos. Con el tiempo necesita más insumos para sostener el rendimiento.","application":"La extracción continua puede alterar el balance de nutrientes y la materia orgánica.","activity":{"type":"choice","question":"¿Qué diagnóstico inicial conviene?","options":["Construir un balance de entradas, cosecha, residuos y pérdidas","Aumentar insumos sin medir","Ignorar la biomasa extraída"],"answer":[0],"success":"El balance permite localizar desequilibrios."}}],"number":"01","references":["Cunningham, W. P. et al. (2023). Principios de Ciencias Ambientales. McGraw-Hill.","Smith, T. M. y Smith, R. L. (2007). Ecología. Pearson.","Hardin, J. y Lodolce, J. P. (2024). Becker. El mundo de la célula. Pearson.","Marino Buslje, C. y Parisi, G. (2019). Aprender para predecir: la bioinformática como herramienta de estudio en biología.","Hodson de Jaramillo, E. et al. (2019). La bioeconomía: nuevo marco para el crecimiento sostenible en América Latina."]};